window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b7966fc1d6ff0aa1"]={"versions": [{"id": "FIG-b7966fc1d6ff0aa1", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Beziehungen zwischen benutzerdefinierten Einschränkungen (Custom Defined Constraints) und speziellen Datengruppen (Special Data Groups, SDG) im Rahmen des AUTOSAR Standardization Templates (<code>AUTOSAR_TPS_StandardizationTemplate</code>). Es modelliert das Metamodell für die Zuordnung von Tailoring-Vorschriften zu SDG-Klassen und textuellen Constraints.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert vier Hauptklassen und deren gerichtete Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>SdgTailoring</code>: Spezialisiert oder annotiert über Stereotypen/Mixins <code>DataFormatElementScope</code> und <code>RestrictionWithSeverity</code>. Besitzt eine gerichtete Referenz <code>+sdgClass</code> mit Multiplizität <code>0..1</code> auf <code>SdgClass</code>.\n</li><li><code>SdgClass</code>: Spezialisiert <code>Identifiable</code> und <code>SdgElementWithGid</code>. Enthält die Attribute <code>+ caption :Boolean [0..1]</code> und <code>+ extendsMetaClass :MetaClassName [0..1]</code>. Besitzt eine gerichtete Assoziation <code>+sdgConstraint</code> mit Multiplizität <code>0..*</code> auf <code>TraceableText</code>.\n</li><li><code>ConstraintTailoring</code>: Spezialisiert <code>DataFormatElementScope</code> und <code>RestrictionWithSeverity</code>. Besitzt eine gerichtete Referenz <code>+constraint</code> mit Multiplizität <code>0..1</code> auf <code>TraceableText</code>.\n</li><li><code>TraceableText</code>: Spezialisiert <code>Identifiable</code>, <code>Paginateable</code> und <code>Traceable</code>. Dient als Ziel für die Einschränkungsdefinitionen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Beziehungen drücken strukturelle Abhängigkeiten zur Entwurfs- und Standardisierungszeit aus: Eine <code>SdgTailoring</code>-Regel referenziert optional eine konkrete <code>SdgClass</code>, welche wiederum mehrere formale Einschränkungen (<code>TraceableText</code>) aggregieren bzw. referenzieren kann. Parallel dazu verweist ein <code>ConstraintTailoring</code> direkt auf ein einzelnes <code>TraceableText</code>-Element.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungskonformität für AUTOSAR-Standardisierungs- und Tailoring-Werkzeuge. Die Multiplizitäten regeln die referenzielle Integrität: Ein Tailoring-Objekt bindet sich an maximal eine Zielentität (<code>0..1</code>), während eine <code>SdgClass</code> beliebig viele Constraints (<code>0..*</code>) über die Rolle <code>+sdgConstraint</code> referenzieren darf. Attribute <code>caption</code> und <code>extendsMetaClass</code> sind optional (<code>0..1</code>).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b12c1e1c8732e853", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Beziehungen zwischen benutzerdefinierten Einschränkungen (Custom Defined Constraints) und speziellen Datengruppen (Special Data Groups, SDG) im Rahmen des AUTOSAR Standardization Templates (<code>AUTOSAR_TPS_StandardizationTemplate</code>). Es modelliert das Metamodell für die Zuordnung von Tailoring-Vorschriften zu SDG-Klassen und textuellen Constraints.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert vier Hauptklassen und deren gerichtete Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>SdgTailoring</code>: Spezialisiert oder annotiert über Stereotypen/Mixins <code>DataFormatElementScope</code> und <code>RestrictionWithSeverity</code>. Besitzt eine gerichtete Referenz <code>+sdgClass</code> mit Multiplizität <code>0..1</code> auf <code>SdgClass</code>.\n</li><li><code>SdgClass</code>: Spezialisiert <code>Identifiable</code> und <code>SdgElementWithGid</code>. Enthält die Attribute <code>+ caption: Boolean [0..1]</code> und <code>+ extendsMetaClass: MetaClassName [0..1]</code>. Besitzt eine gerichtete Assoziation <code>+sdgConstraint</code> mit Multiplizität <code>0..*</code> auf <code>TraceableText</code>.\n</li><li><code>ConstraintTailoring</code>: Spezialisiert <code>DataFormatElementScope</code> und <code>RestrictionWithSeverity</code>. Besitzt eine gerichtete Referenz <code>+constraint</code> mit Multiplizität <code>0..1</code> auf <code>TraceableText</code>.\n</li><li><code>TraceableText</code>: Spezialisiert <code>Identifiable</code>, <code>Paginateable</code> und <code>Traceable</code>. Dient als Ziel für die Einschränkungsdefinitionen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Beziehungen drücken strukturelle Abhängigkeiten zur Entwurfs- und Standardisierungszeit aus: Eine <code>SdgTailoring</code>-Regel referenziert optional eine konkrete <code>SdgClass</code>, welche wiederum mehrere formale Einschränkungen (<code>TraceableText</code>) aggregieren bzw. referenzieren kann. Parallel dazu verweist ein <code>ConstraintTailoring</code> direkt auf ein einzelnes <code>TraceableText</code>-Element.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungskonformität für AUTOSAR-Standardisierungs- und Tailoring-Werkzeuge. Die Multiplizitäten regeln die referenzielle Integrität: Ein Tailoring-Objekt bindet sich an maximal eine Zielentität (<code>0..1</code>), während eine <code>SdgClass</code> beliebig viele Constraints (<code>0..*</code>) über die Rolle <code>+sdgConstraint</code> referenzieren darf. Attribute <code>caption</code> und <code>extendsMetaClass</code> sind optional (<code>0..1</code>).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-59b7c64a5a386771", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Beziehungen zwischen benutzerdefinierten Einschränkungen (Custom Defined Constraints) und speziellen Datengruppen (Special Data Groups, SDG) im Rahmen des AUTOSAR Standardization Templates (<code>AUTOSAR_TPS_StandardizationTemplate</code>). Es modelliert das Metamodell für die Zuordnung von Tailoring-Vorschriften zu SDG-Klassen und textuellen Constraints.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert vier Hauptklassen und deren gerichtete Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>SdgTailoring</code>: Spezialisiert oder annotiert über Stereotypen/Mixins <code>DataFormatElementScope</code> und <code>RestrictionWithSeverity</code>. Besitzt eine gerichtete Referenz <code>+sdgClass</code> mit Multiplizität <code>0..1</code> auf <code>SdgClass</code>.\n</li><li><code>SdgClass</code>: Spezialisiert <code>Identifiable</code> und <code>SdgElementWithGid</code>. Enthält die Attribute <code>+ caption: Boolean [0..1]</code> und <code>+ extendsMetaClass: MetaClassName [0..1]</code>. Besitzt eine gerichtete Assoziation <code>+sdgConstraint</code> mit Multiplizität <code>0..*</code> auf <code>TraceableText</code>.\n</li><li><code>ConstraintTailoring</code>: Spezialisiert <code>DataFormatElementScope</code> und <code>RestrictionWithSeverity</code>. Besitzt eine gerichtete Referenz <code>+constraint</code> mit Multiplizität <code>0..1</code> auf <code>TraceableText</code>.\n</li><li><code>TraceableText</code>: Spezialisiert <code>Identifiable</code>, <code>Paginateable</code> und <code>Traceable</code>. Dient als Ziel für die Einschränkungsdefinitionen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Beziehungen drücken strukturelle Abhängigkeiten zur Entwurfs- und Standardisierungszeit aus: Eine <code>SdgTailoring</code>-Regel referenziert optional eine konkrete <code>SdgClass</code>, welche wiederum mehrere formale Einschränkungen (<code>TraceableText</code>) aggregieren bzw. referenzieren kann. Parallel dazu verweist ein <code>ConstraintTailoring</code> direkt auf ein einzelnes <code>TraceableText</code>-Element.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungskonformität für AUTOSAR-Standardisierungs- und Tailoring-Werkzeuge. Die Multiplizitäten regeln die referenzielle Integrität: Ein Tailoring-Objekt bindet sich an maximal eine Zielentität (<code>0..1</code>), während eine <code>SdgClass</code> beliebig viele Constraints (<code>0..*</code>) über die Rolle <code>+sdgConstraint</code> referenzieren darf. Attribute <code>caption</code> und <code>extendsMetaClass</code> sind optional (<code>0..1</code>).</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-b7966fc1d6ff0aa1", "to": "FIG-b12c1e1c8732e853", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Typografische Bereinigung in Klasse <code>SdgClass</code>: Leerzeichen vor dem Doppelpunkt bei Attributdefinitionen entfernt (<code>+ caption :Boolean [0..1]</code> -&gt; <code>+ caption: Boolean [0..1]</code>, <code>+ extendsMetaClass :MetaClassName [0..1]</code> -&gt; <code>+ extendsMetaClass: MetaClassName [0..1]</code>).\n</li></ul>"}, {"from": "FIG-b12c1e1c8732e853", "to": "FIG-59b7c64a5a386771", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
